import{_ as e,o as l,c as a,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Rullst Blueprints Roadmap 🗺️","description":"","frontmatter":{},"headers":[],"relativePath":"reference/blueprints_roadmap.md","filePath":"reference/blueprints_roadmap.md"}'),r={name:"reference/blueprints_roadmap.md"};function n(o,t,s,d,c,u){return l(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="rullst-blueprints-roadmap-🗺️" tabindex="-1">Rullst Blueprints Roadmap 🗺️ <a class="header-anchor" href="#rullst-blueprints-roadmap-🗺️" aria-label="Permalink to &quot;Rullst Blueprints Roadmap 🗺️&quot;">​</a></h1><h3 id="the-ultimate-high-performance-blueprints-collection-for-rullst" tabindex="-1"><em>&quot;The Ultimate High-Performance Blueprints Collection for Rullst&quot;</em> <a class="header-anchor" href="#the-ultimate-high-performance-blueprints-collection-for-rullst" aria-label="Permalink to &quot;*&quot;The Ultimate High-Performance Blueprints Collection for Rullst&quot;*&quot;">​</a></h3><p>This document maps the expansion plan for the Rullst <strong>Starter Blueprints</strong> ecosystem. The goal is to provide developers and agencies with complete, &quot;production-ready&quot; solutions that highlight the performance, security, and productivity advantages of the Rust + Rullst ecosystem.</p><hr><h2 id="🚀-blueprints-design-philosophy" tabindex="-1">🚀 Blueprints Design Philosophy <a class="header-anchor" href="#🚀-blueprints-design-philosophy" aria-label="Permalink to &quot;🚀 Blueprints Design Philosophy&quot;">​</a></h2><p>Every blueprint added to the CLI must meet three fundamental principles:</p><ol><li><strong>Immediate Wow Factor:</strong> Beautiful, responsive interfaces (Dark Mode, Glassmorphism, Micro-animations) and highly interactive via HTMX/Tailwind.</li><li><strong>Native Rust/Rullst Features:</strong> Practically demonstrate Rust&#39;s unfair advantage (low RAM usage, safe concurrency, parallel processing, type safety, robust WebSockets).</li><li><strong>Production-Ready:</strong> Automatically generate <code>.env.example</code>, database configurations with concurrency locks, and a bulletproof <code>.gitignore</code>.</li></ol><hr><h2 id="🗺️-new-blueprints-roadmap-ordered-from-easiest-to-hardest" tabindex="-1">🗺️ New Blueprints Roadmap (Ordered from Easiest to Hardest) <a class="header-anchor" href="#🗺️-new-blueprints-roadmap-ordered-from-easiest-to-hardest" aria-label="Permalink to &quot;🗺️ New Blueprints Roadmap (Ordered from Easiest to Hardest)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">ID</th><th style="text-align:left;">Blueprint Name</th><th style="text-align:left;">Technical Focus in Rullst</th><th style="text-align:left;">Commercial Differentiator</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>4</strong></td><td style="text-align:left;">💼 ERP Pocket (Inventory)</td><td style="text-align:left;">Embedded SQLite + <code>rullst::nexus</code> (Auto-CMS) + Single Binary</td><td style="text-align:left;">Small/Medium businesses with an offline-first, crash-immune system.</td></tr><tr><td style="text-align:left;"><strong>5</strong></td><td style="text-align:left;">📡 Uptime Monitoring Service</td><td style="text-align:left;">Asynchronous Workers (<code>rullst::queue</code>) + Health Checks</td><td style="text-align:left;">Uptime Kuma alternative running on a $5 VPS with zero memory usage.</td></tr><tr><td style="text-align:left;"><strong>6</strong></td><td style="text-align:left;">📋 Member/Club Management</td><td style="text-align:left;"><code>#[derive(Validate)]</code> + Nexus + PDF Receipt Generation</td><td style="text-align:left;">Member registration and billing for gyms, clubs, and condominiums.</td></tr><tr><td style="text-align:left;"><strong>7</strong></td><td style="text-align:left;">🤖 AI Agent &amp; RAG Boilerplate</td><td style="text-align:left;"><code>rullst::ai</code> (Ollama/Gemini/OpenAI) + Local Vector Embedding</td><td style="text-align:left;">Intelligent parsing of local and private PDF/TXT documents.</td></tr><tr><td style="text-align:left;"><strong>8</strong></td><td style="text-align:left;">🪙 AI Credit-Based SaaS</td><td style="text-align:left;">Streaming (SSE) + <code>rullst-orm</code> (Concurrency Lock) + Stripe</td><td style="text-align:left;">AI SaaS platforms with token consumption secured against race conditions.</td></tr><tr><td style="text-align:left;"><strong>9</strong></td><td style="text-align:left;">🏥 Scheduling &amp; Clinics</td><td style="text-align:left;">HTMX Calendar + Cron Scheduler + Double-Booking Locks</td><td style="text-align:left;">Barbershops, doctors, and freelancers with duplicate reservation prevention.</td></tr><tr><td style="text-align:left;"><strong>10</strong></td><td style="text-align:left;">🚪 Biometric Access Control</td><td style="text-align:left;"><code>rullst::routing</code> (WebSockets) + Real-time Concierge Panel</td><td style="text-align:left;">Concierge systems, gyms, and electronic timeclocks with zero lag.</td></tr><tr><td style="text-align:left;"><strong>11</strong></td><td style="text-align:left;">📈 Affiliate Checkout</td><td style="text-align:left;">Fast SSR (&lt;100ms) + Commission Splits + Landing Page</td><td style="text-align:left;">Sales pages with a 100 Lighthouse Score for maximum conversion.</td></tr><tr><td style="text-align:left;"><strong>12</strong></td><td style="text-align:left;">🏢 B2B Multi-Tenant Platform</td><td style="text-align:left;"><code>rullst::multitenant</code> (subdomains) + RBAC (Enums) + <code>rullst::mail</code></td><td style="text-align:left;">Secure, isolated enterprise software for selling corporate licenses.</td></tr><tr><td style="text-align:left;"><strong>13</strong></td><td style="text-align:left;">💬 Discord-Like Realtime Chat</td><td style="text-align:left;"><strong>Rullst Live</strong> (Server-Driven UI) + WebSockets on Tokio</td><td style="text-align:left;">Scalable, concurrent chat rooms with low infrastructure cost.</td></tr><tr><td style="text-align:left;"><strong>14</strong></td><td style="text-align:left;">🛵 Delivery / Food App</td><td style="text-align:left;">Background Queue (<code>rullst::queue</code>) + Order State</td><td style="text-align:left;">Asynchronous delivery status processing and email notifications.</td></tr></tbody></table><hr><h2 id="🔍-highlighted-architectural-details" tabindex="-1">🔍 Highlighted Architectural Details <a class="header-anchor" href="#🔍-highlighted-architectural-details" aria-label="Permalink to &quot;🔍 Highlighted Architectural Details&quot;">​</a></h2><h3 id="🪙-8-ai-credit-based-saas-the-token-burner" tabindex="-1">🪙 8. AI Credit-Based SaaS (The Token-Burner) <a class="header-anchor" href="#🪙-8-ai-credit-based-saas-the-token-burner" aria-label="Permalink to &quot;🪙 8. AI Credit-Based SaaS (The Token-Burner)&quot;">​</a></h3><ul><li><strong>Architecture:</strong> Clean chat interface consuming data via native Server-Sent Events (SSE) for fluid AI response streaming.</li><li><strong>Data Security:</strong> <code>rullst-orm</code> implements strict transaction locks to ensure that if a user&#39;s credit balance reaches zero simultaneously in two different tabs, the system aborts token generation before finalizing costly calls to the LLM.</li><li><strong>Monetization:</strong> Integrated Stripe checkout with usage-based billing and a self-managed billing portal.</li></ul><h3 id="🏢-12-b2b-multi-tenant-platform-the-corporate-boilerplate" tabindex="-1">🏢 12. B2B Multi-Tenant Platform (The Corporate Boilerplate) <a class="header-anchor" href="#🏢-12-b2b-multi-tenant-platform-the-corporate-boilerplate" aria-label="Permalink to &quot;🏢 12. B2B Multi-Tenant Platform (The Corporate Boilerplate)&quot;">​</a></h3><ul><li><strong>Isolation:</strong> Uses the native <code>rullst::multitenant</code> module, which intercepts HTTP requests and dynamically injects the <code>tenant_id</code> scope into all SQL queries throughout the request lifecycle, preventing accidental data leaks between companies.</li><li><strong>Permissions (RBAC):</strong> Role structures (<code>Admin</code>, <code>Member</code>, <code>Billing</code>) based on safe Rust enums, validated via middlewares before dispatching to controllers.</li><li><strong>Invitations:</strong> Cryptographically tokenized email invitation flow with a 24-hour expiration using the native <code>rullst::mail</code> mailer.</li></ul><h3 id="💬-13-discord-like-realtime-chat" tabindex="-1">💬 13. Discord-Like Realtime Chat <a class="header-anchor" href="#💬-13-discord-like-realtime-chat" aria-label="Permalink to &quot;💬 13. Discord-Like Realtime Chat&quot;">​</a></h3><ul><li><strong>No Complex JS:</strong> Uses <strong>Rullst Live</strong> to maintain the chat room state on the server. Every message submitted via an HTMX form is processed, added to the thread&#39;s broadcasting channel, and rendered directly by the server, updating client DOMs via real-time WebSockets.</li><li><strong>Scale:</strong> Utilizes Rust&#39;s efficient <code>Tokio</code> runtime threads, allowing thousands of persistent active WebSocket connections while consuming less than 50MB of RAM on the server.</li></ul><h3 id="🏥-9-scheduling-clinics-the-scheduler" tabindex="-1">🏥 9. Scheduling &amp; Clinics (The Scheduler) <a class="header-anchor" href="#🏥-9-scheduling-clinics-the-scheduler" aria-label="Permalink to &quot;🏥 9. Scheduling &amp; Clinics (The Scheduler)&quot;">​</a></h3><ul><li><strong>Conflict Prevention:</strong> Database transactions executed with a strict <code>SERIALIZABLE</code> isolation level or pessimistic locking to prevent double-booking at the exact millisecond of confirmation.</li><li><strong>Integrated Cron:</strong> Reminder registration via Rullst&#39;s native Cron to fetch appointments in the next 2 hours and trigger automatic notifications without the need for external schedulers like Sidekiq or Celery.</li></ul><h3 id="🤖-7-ai-agent-rag-boilerplate-ai-native" tabindex="-1">🤖 7. AI Agent &amp; RAG Boilerplate (AI-Native) <a class="header-anchor" href="#🤖-7-ai-agent-rag-boilerplate-ai-native" aria-label="Permalink to &quot;🤖 7. AI Agent &amp; RAG Boilerplate (AI-Native)&quot;">​</a></h3><ul><li><strong>Structure:</strong> Intuitive file upload interface where Rullst converts the document, calculates embeddings using local models or configured APIs, and stores the vector data in the embedded SQLite database.</li><li><strong>Flexibility:</strong> Flexible configuration via <code>rullst::ai</code> allowing instant toggling between external commercial LLMs (Gemini, OpenAI) and local instances (Ollama / Llama 3) with a single environment variable.</li></ul>',22)])])}const m=e(r,[["render",n]]);export{h as __pageData,m as default};
